strip_items = []
for idx, (code, url) in enumerate(strip_raw):
    filename = f"strip_{idx}_{code}.avif"
    local_path = f"public/community_home/strip/{filename}"
    rel_path = f"/community_home/strip/{filename}"
    
    if not os.path.exists(local_path) or os.path.getsize(local_path) == 0:
        try:
            req = urllib.request.Request(url, headers={'User-Agent': 'Mozilla/5.0'})
            with urllib.request.urlopen(req) as resp, open(local_path, 'wb') as f:
                f.write(resp.read())
            print(f"Downloaded strip {code}")
        except Exception as e:
            print(f"Err strip {code}: {e}")
            rel_path = url
            
    strip_items.append({"id": code, "alt": f"[{code}]", "src": rel_path})

print(f"Strip completed with {len(strip_items)} items.")
